293:       if (inBounds(x - 1, y) && state.grid[idx(x - 1, y)].road) return true;
294:       if (inBounds(x + 1, y) && state.grid[idx(x + 1, y)].road) return true;
295:       if (inBounds(x, y - 1) && state.grid[idx(x, y - 1)].road) return true;
296:       if (inBounds(x, y + 1) && state.grid[idx(x, y + 1)].road) return true;
297:     }
