304:     let wild = false;
305:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
306:       const t = state.grid[idx(xx, yy)];
307:       if (t.terrain === 'water') return { ok: false, msg: 'Tidak bisa membangun di atas air.' };
308:       if (t.road) return { ok: false, msg: 'Petak sudah dipakai jalan.' };
309:       if (t.b) {
310:         if (def.kind === 'road') return { ok: false, msg: 'Ada bangunan di petak ini.' };
311:         if (t.b.defId === 'tree' || t.b.defId === 'rock') wild = true;
312:         else return { ok: false, msg: 'Petak sudah terisi.' };
313:       }
314:     }
315:     if (wild) return { ok: false, msg: 'Bersihkan pohon/batu dengan alat bongkar dulu.' };
316:     if (def.kind !== 'road' && def.kind !== 'decor') {
317:       let ok = false;
