319:       ok = roadAccess(test);
320:       if (!ok) return { ok: false, msg: 'Butuh akses jalan di sebelahnya.' };
321:     }
322:     if (!opts.free && state.money < def.cost) return { ok: false, msg: 'Kas kota tidak cukup.' };
