1031:   function updateMinimap() {
1032:     const cv = $('#minimap'); if (!cv || !state) return;
1033:     const c = cv.getContext('2d');
1034:     const w = cv.width, h = cv.height;
1035:     c.clearRect(0, 0, w, h);
1036:     c.fillStyle = '#8ccfe0'; c.fillRect(0, 0, w, h);
1037:     const size = state.gridSize;
1038:     const padX = (w - (Math.min(w, h) - 16)) / 2 + 8;
1039:     const padY = (h - (Math.min(w, h) - 16)) / 2 + 8;
1040:     const cell = (Math.min(w, h) - 16) / size;
1041:     for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
1042:       const t = state.grid[idx(x, y)];
1043:       let col = t.terrain === 'water' ? '#3b93b3' : t.terrain === 'sand' ? '#e6d29c' : '#87c568';
1044:       if (t.road) col = '#59626a';
1045:       if (t.b) {
1046:         const d = defOf(t.b);
1047:         if (d.kind === 'zone-r') col = '#3aa96b';
1048:         else if (d.kind === 'zone-c') col = '#3b8fd4';
1049:         else if (d.kind === 'zone-i') col = '#d9a03c';
1050:         else if (d.cat === 'service') col = '#e05a8b';
1051:         else if (d.cat === 'fun') col = '#f0a33e';
1052:         else if (d.kind === 'decor') col = t.b.defId === 'tree' ? '#4f9b54' : '#7bc46a';
1053:         else col = '#6f8f89';
1054:       }
1055:       c.fillStyle = col;
1056:       c.fillRect(padX + x * cell, padY + y * cell, Math.ceil(cell), Math.ceil(cell));
1057:     }
1058:     // camera marker (approx)
1059:     const gx = (cam.x / 32 + cam.y / 16) / 2;
1060:     const gy = (cam.y / 16 - cam.x / 32) / 2;
1061:     c.strokeStyle = 'rgba(255,255,255,.95)'; c.lineWidth = 2;
1062:     c.strokeRect(padX + gx * cell - 8, padY + gy * cell - 8, 16, 16);
1063:     c.fillStyle = 'rgba(255,255,255,.9)';
1064:     c.beginPath(); c.arc(padX + gx * cell, padY + gy * cell, 2.5, 0, 7); c.fill();
1065:     // frame
1066:     c.strokeStyle = 'rgba(9,57,62,.15)'; c.lineWidth = 1; c.strokeRect(0, 0, w, h);
1067:   }
