  poly(ctx, [{ x: g.T.x - 2, y: g.T.y - 29 }, { x: g.R.x + 2, y: g.R.y - 29 }, { x: (g.T.x + g.R.x) / 2, y: (g.T.y + g.R.y) / 2 - 41 }], '#9b6949', '#80583f', 1);
